// Rendering baselines for the real-agent corpus (test/corpus, see SOURCES.md).
//
// Each document's patch (generated by ReadoutCore and kept current by
// CorpusTests) is rendered in WebKit, light and dark, with every lazy
// renderer (code highlighting, KaTeX, Mermaid) settled. Two baselines per
// document and theme:
//
//   snapshots/<doc>-<theme>.json  the whole document: every block's slot,
//                                 position, height, a hash of its text, and a
//                                 fingerprint of the computed styles and sizes
//                                 of everything inside it.
//                                 Small, exact and diffable in review.
//   screenshots/<doc>-<theme>.png pixels of the first 1200 px, compared
//                                 with a small anti-aliasing tolerance.
//
// (Full-page pixel baselines for 30 documents would add ~100 MB to the
// repository per rendering change; the snapshot covers the whole page
// instead, and full-page screenshots are always written to
// test/out/corpus/full for review, uploaded by CI as an artifact.)
//
// On a mismatch: the changed blocks are listed, the actual image and a diff
// image are written to test/out/corpus, and the run fails.
//
// Usage: node test/corpus.test.mjs [--update] [name-filter]
//   --update  rewrite baselines. Baselines must come from CI's WebKit (fonts
//             differ between machines): use the corpus-actual artifact.
import { webkit } from 'playwright';
import http from 'node:http';
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs';
import { extname, join } from 'node:path';
import { PNG } from 'pngjs';
import pixelmatch from 'pixelmatch';

const args = process.argv.slice(2);
const update = args.includes('--update');
const filter = args.find(a => !a.startsWith('--')) || '';

const CORPUS = 'test/corpus';
const SNAPS = `${CORPUS}/snapshots`;
const SHOTS = `${CORPUS}/screenshots`;
const OUT = 'test/out/corpus';
for (const d of [SNAPS, SHOTS, OUT, `${OUT}/full`, `${OUT}/actual/snapshots`, `${OUT}/actual/screenshots`]) mkdirSync(d, { recursive: true });

const WIDTH = 900;
const TOP = 1200;                  // px of pixel baseline per document
const TILE = 8000;                 // WebKit caps a capture at 32767 px
// Anti-aliasing differs by a few pixels between otherwise identical runs; a
// real rendering change moves far more than this.
const PIXEL_THRESHOLD = 0.1;       // per-pixel color distance (pixelmatch)
const MAX_DIFF_RATIO = 0.0005;     // share of pixels allowed to differ

const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.woff2': 'font/woff2', '.woff': 'font/woff', '.ttf': 'font/ttf' };
const server = http.createServer((req, res) => {
  const p = join('build/Web', decodeURIComponent(req.url.split('?')[0]));
  if (!existsSync(p)) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'content-type': types[extname(p)] || 'application/octet-stream' });
  res.end(readFileSync(p));
}).listen(0);
const base = `http://127.0.0.1:${server.address().port}`;

const browser = await webkit.launch();
const docs = readdirSync(`${CORPUS}/patches`).filter(f => f.endsWith('.json') && f.includes(filter)).sort();
let failures = 0;
const summary = [];

async function render(patch, dark) {
  const page = await browser.newPage({ viewport: { width: WIDTH, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.addInitScript(dbg => {
    window.__debugParts = dbg;
    // Deterministic highlighting on a busy CI machine (see highlight.js).
    window.READOUT_TOKENIZE_LIMIT = 60000;
    window.__msgs = [];
    window.webkit = { messageHandlers: { readout: { postMessage: m => window.__msgs.push(m) } } };
  }, process.env.CORPUS_DEBUG === '1');
  await page.goto(`${base}/reader.html`);
  await page.waitForFunction(() => window.readout && window.__msgs.some(m => m.type === 'ready'));
  await page.evaluate(d => window.readout.setAppearance({ dark: d, accent: '#0a84ff', width: 'narrow', fontSize: 16 }), dark);
  await page.evaluate(p => window.readout.apply(p), patch);
  // Large documents use content-visibility, so blocks never scrolled into
  // view keep estimated heights. Render everything for a deterministic page.
  await page.evaluate(() => document.getElementById('ro-doc').classList.remove('cv'));
  // Walk the page so every lazy renderer fires, then wait until none is pending.
  const walk = async () => {
    const height = await page.evaluate(() => document.scrollingElement.scrollHeight);
    for (let y = 0; y < height; y += 800) {
      await page.evaluate(top => window.scrollTo(0, top), y);
      await page.waitForTimeout(20);
    }
  };
  await walk();
  await page.waitForFunction(() =>
    !document.querySelector('.code-block[data-hl="pending"], .code-block[data-hl="loading"], .code-block[data-hl="recheck"], .mermaid-block.busy')
    && [...document.querySelectorAll('.mermaid-block')].every(b => b.classList.contains('done') || b.querySelector('.mermaid-error'))
    && !document.querySelector('.math:not(.done), .math-block:not(.done)'),
  null, { timeout: 30000 }).catch(async () => {
    const left = await page.evaluate(() => [...document.querySelectorAll('.code-block[data-hl="pending"], .code-block[data-hl="loading"], .mermaid-block:not(.done), .math:not(.done), .math-block:not(.done)')]
      .slice(0, 5).map(e => `${e.className}${e.dataset.lang ? ` (${e.dataset.lang}: ${e.dataset.hl})` : ''}`));
    errors.push(`lazy rendering did not settle within 30 s: ${left.join('; ')}`);
  });
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(200);

  const snapshot = await page.evaluate(() => {
    const STYLE = ['fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'lineHeight', 'color', 'backgroundColor',
      'borderTopWidth', 'borderTopColor', 'borderLeftWidth', 'borderLeftColor', 'textDecorationLine', 'textAlign', 'display'];
    const fnv = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
    const describe = el => {
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return `${el.tagName}.${el.getAttribute('class') || ''}|${STYLE.map(k => cs[k]).join('|')}|${Math.round(r.width)}x${Math.round(r.height)}`;
    };
    const top0 = document.getElementById('ro-doc').getBoundingClientRect().top + window.scrollY;
    const blocks = [...document.querySelectorAll('#ro-doc > .blk, #ro-doc > .del-mark')].map(b => {
      const parts = [describe(b)];
      // Mermaid SVG internals carry generated ids; the SVG's box is enough.
      for (const el of b.querySelectorAll('*')) if (!el.closest('svg') || el.tagName === 'svg') parts.push(describe(el));
      const r = b.getBoundingClientRect();
      return {
        slot: +b.dataset.slot || 0, kind: (b.className.match(/k-(\w+)/) || [, 'del'])[1],
        top: Math.round(r.top + window.scrollY - top0), h: Math.round(r.height),
        style: fnv(parts.join('\n')),
        content: fnv(b.textContent),
        ...(window.__debugParts ? { parts } : {}),
        text: b.textContent.replace(/\s+/g, ' ').trim().slice(0, 48),
      };
    });
    return { height: document.scrollingElement.scrollHeight, blocks };
  });

  const top = await page.screenshot({ animations: 'disabled', caret: 'hide', fullPage: true,
    clip: { x: 0, y: 0, width: WIDTH, height: Math.min(TOP, snapshot.height) } });
  const tiles = [];
  for (let y = 0; y < snapshot.height; y += TILE) {
    tiles.push(await page.screenshot({ fullPage: true, animations: 'disabled', caret: 'hide',
      clip: { x: 0, y, width: WIDTH, height: Math.min(TILE, snapshot.height - y) } }));
  }
  await page.close();
  return { snapshot, top, tiles, errors };
}

function compareSnapshot(name, got) {
  const path = `${SNAPS}/${name}.json`;
  const text = JSON.stringify(got, null, 1) + '\n';
  writeFileSync(`${OUT}/actual/snapshots/${name}.json`, text);
  if (update) { writeFileSync(path, text); return null; }
  if (!existsSync(path)) return 'no snapshot baseline';
  const want = JSON.parse(readFileSync(path, 'utf8'));
  const changes = [];
  if (want.height !== got.height) changes.push(`page height ${want.height} -> ${got.height}`);
  if (want.blocks.length !== got.blocks.length) changes.push(`blocks ${want.blocks.length} -> ${got.blocks.length}`);
  const n = Math.min(want.blocks.length, got.blocks.length);
  let shown = 0;
  for (let i = 0; i < n && shown < 8; i++) {
    const a = want.blocks[i], b = got.blocks[i];
    const what = [];
    if (a.h !== b.h) what.push(`height ${a.h} -> ${b.h}`);
    if (a.style !== b.style) what.push('styles/inner layout');
    if (a.kind !== b.kind) what.push(`kind ${a.kind} -> ${b.kind}`);
    if (a.slot !== b.slot) what.push(`slot ${a.slot} -> ${b.slot}`);
    if (a.content !== b.content) what.push(`text "${a.text}" -> "${b.text}"`);
    // A moved block whose own height and styles are unchanged only follows an earlier change.
    if (!what.length && a.top !== b.top && changes.length === 0) what.push(`top ${a.top} -> ${b.top}`);
    if (what.length) { shown++; changes.push(`#${i} ${b.kind} "${b.text}": ${what.join(', ')}`); }
  }
  return changes.length ? changes.join('\n      ') : null;
}

function compareTop(name, png) {
  const shot = `${name}.png`;
  writeFileSync(`${OUT}/actual/screenshots/${shot}`, png);
  if (update) { writeFileSync(`${SHOTS}/${shot}`, png); return null; }
  if (!existsSync(`${SHOTS}/${shot}`)) return 'no screenshot baseline';
  const want = PNG.sync.read(readFileSync(`${SHOTS}/${shot}`));
  const got = PNG.sync.read(png);
  if (want.width !== got.width || want.height !== got.height) {
    writeFileSync(`${OUT}/${shot}`, png);
    return `screenshot size ${got.width}x${got.height} != baseline ${want.width}x${want.height}`;
  }
  const diff = new PNG({ width: got.width, height: got.height });
  const changed = pixelmatch(want.data, got.data, diff.data, got.width, got.height, { threshold: PIXEL_THRESHOLD });
  if (changed / (got.width * got.height) <= MAX_DIFF_RATIO) return null;
  writeFileSync(`${OUT}/${shot}`, png);
  writeFileSync(`${OUT}/${name}.diff.png`, PNG.sync.write(diff));
  return `top ${TOP}px differs in ${changed} px (${(changed / (got.width * got.height) * 100).toFixed(3)}%)`;
}

for (const file of docs) {
  const doc = file.replace(/\.json$/, '');
  const patch = JSON.parse(readFileSync(`${CORPUS}/patches/${file}`, 'utf8'));
  for (const theme of ['light', 'dark']) {
    const name = `${doc}-${theme}`;
    const { snapshot, top, tiles, errors } = await render(patch, theme === 'dark');
    tiles.forEach((png, i) => writeFileSync(`${OUT}/full/${name}-${i + 1}.png`, png));
    const problems = [...errors];
    const s = compareSnapshot(name, snapshot);
    if (s) problems.push(s);
    const t = compareTop(name, top);
    if (t) problems.push(t);
    if (problems.length) {
      failures++;
      summary.push(name);
      console.log(`FAIL: ${name}\n      ${problems.join('\n      ')}`);
    } else {
      console.log(`${update ? 'updated' : 'ok'}: ${name} (${snapshot.blocks.length} blocks, ${snapshot.height} px)`);
    }
  }
}

await browser.close();
server.close();
if (summary.length) console.log(`changed: ${summary.join(', ')}\nActual baselines: ${OUT}/actual; diffs and full pages: ${OUT}.`);
console.log(`${docs.length} documents x 2 themes, ${failures} failing`);
process.exit(failures ? 1 : 0);
